    if horizontal_walls:
        # Travel perpendicular to horizontal walls, down or up from the seed.
        direction = 1 if row_walls[0] > sr else -1
        walls = sorted((r for r in row_walls if (r - sr) * direction > 0), reverse=(direction < 0))
